//! Event sequences of the Transport Stream demuxer across errors, which no
//! independent implementation can judge
//!
//! Only sequences that hold an error or unsynchronized input have a snapshot;
//! a stream that demuxes cleanly is checked by assertion instead.

#[cfg(test)]
#[cfg(feature = "alloc")]
#[expect(
    clippy::indexing_slicing,
    clippy::arithmetic_side_effects,
    reason = "streams are cut at constant offsets well inside their length"
)]
mod tests {
    use mpeg2_systems::ts::demux::{Demuxer, DemuxerConfig, Event};

    /// A Transport Stream FFmpeg wrote, generated by `cargo xtask fixtures`
    const STANDARD_188: &[u8] = include_bytes!("fixtures/188.ts");

    /// Leading bytes of an [`Event::Unsynchronized`] a snapshot shows
    const PREVIEW_LENGTH: usize = 16;

    /// The event as `Debug` prints it, but an [`Event::Unsynchronized`] as its
    /// length and leading bytes, so a snapshot stays a readable event list
    fn describe(event: &Event<'_>) -> String {
        let Event::Unsynchronized { bytes } = event else {
            return format!("{event:?}");
        };
        let preview: Vec<String> = bytes
            .iter()
            .take(PREVIEW_LENGTH)
            .map(|byte| format!("{byte:02x}"))
            .collect();
        let ellipsis = if bytes.len() > PREVIEW_LENGTH {
            " .."
        } else {
            ""
        };
        format!(
            "Unsynchronized {{ bytes: {} bytes [{}{ellipsis}] }}",
            bytes.len(),
            preview.join(" ")
        )
    }

    fn events_of(stream: &[u8]) -> Vec<String> {
        let mut demuxer = Demuxer::new(DemuxerConfig::default());
        let mut events = Vec::new();
        demuxer.handle_input(stream);
        while let Some(event) = demuxer.poll_event() {
            events.push(describe(&event));
        }
        demuxer.finish();
        while let Some(event) = demuxer.poll_event() {
            events.push(describe(&event));
        }
        events
    }

    #[test]
    fn standard_188_byte_stream_behind_leading_garbage() {
        let mut stream = vec![0xFF; 500];
        stream.extend_from_slice(STANDARD_188);
        insta::assert_debug_snapshot!(events_of(&stream));
    }

    #[test]
    fn standard_188_byte_stream_cut_inside_its_last_packet() {
        insta::assert_debug_snapshot!(events_of(&STANDARD_188[..STANDARD_188.len() - 100]));
    }

    #[test]
    fn standard_188_byte_stream_with_a_pat_whose_crc_32_fails() {
        let mut stream = STANDARD_188.to_vec();
        stream[188 + 20] ^= 0x01;
        insta::assert_debug_snapshot!(events_of(&stream));
    }

    #[test]
    fn standard_188_byte_stream_with_two_sync_bytes_missing_in_a_row() {
        let mut stream = STANDARD_188.to_vec();
        stream[188 * 10] = 0x00;
        stream[188 * 11] = 0x00;
        insta::assert_debug_snapshot!(events_of(&stream));
    }
}
